// Quality / error metric executor (package s2).
//
// Host-visible surface (plain .cpp safe): everything here is declared here and
// defined + explicitly instantiated in nppi_quality_metrics_executor.cu.  The
// public wrappers are generated by mpp_scripts/gen_family.py
// (mpp_scripts/families/nppi_{quality_index,count_in_range,mse,psnr,...}.json).
//
// Semantics are pinned by the standalone 5090 probes
// (tools/5090_probes_s2/s2_probe*.cu) and the differential tests:
//
//  * QualityIndex: Q = 4*cov*ma*mb / ((ma^2+mb^2)*(va+vb)) with sample
//    (n-1) variances/covariance.  C3/AC4 outputs store one float per colour
//    channel; NPP computes each channel's covariance from its own means but
//    uses the channel-0 means (numerator) and channel-0 (va+vb) denominator
//    for every channel.  The zero-variance check is per channel.  A channel
//    with zero variance in either source raises NPP_QUALITY_INDEX_ERROR and no
//    output is written (a 1x1 ROI yields NaN and succeeds).
//  * CountInRange: inclusive [lower, upper] bounds read from host arrays
//    (scalars for C1R), counts written as `int` to device memory, one per
//    colour channel (alpha ignored).  lower > upper -> NPP_RANGE_ERROR.
//  * MSE / PSNR: per-channel mean squared error; PSNR = 10*log10(255^2/MSE)
//    for 8u (infinite when the images are identical).
//  * MSEBatch/PSNRBatch: descriptor lists live on the device.  The plain form
//    measures oSizeROI in every image (descriptor nStep); the Advanced form
//    uses each descriptor's oSize.
//  * HistogramEven/Range C3/AC4: nLevels/even levels are host arrays, Range
//    level pointers are device pointers; bin k covers [level[k], level[k+1])
//    with the last level exclusive; alpha is ignored.
//  * RectStdDev: integral-image box statistics, dst(x,y) covers the window at
//    (x + rect.x, y + rect.y); 32s_Sfs truncates the square root and applies
//    an arithmetic shift by nScaleFactor (left shift for negative scales).
#ifndef NPPI_QUALITY_METRICS_EXECUTOR_H
#define NPPI_QUALITY_METRICS_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace statistics {

// ---------------------------------------------------------------------------
// Device-buffer size helpers (exact NVIDIA NPP 13.4 values where measured).
// ---------------------------------------------------------------------------
NppStatus qualityIndexGetBufferHostSize(NppiSize oSizeROI, int channels, int *hpBufferSize);
NppStatus countInRangeGetBufferHostSize(NppiSize oSizeROI, int channels, bool alpha, int elemSize,
                                        int *hpBufferSize);
NppStatus mseGetBufferHostSize(NppiSize oSizeROI, int channels, int *hpBufferSize);
NppStatus psnrGetBufferHostSize(NppiSize oSizeROI, int channels, int *hpBufferSize);
NppStatus mseBatchGetBufferHostSize(NppiSize oSizeROI, int channels, int *hpBufferSize);
NppStatus psnrBatchGetBufferHostSize(NppiSize oSizeROI, int channels, int *hpBufferSize);

// ---------------------------------------------------------------------------
// QualityIndex
// ---------------------------------------------------------------------------
// channels: packed channels per pixel (1/3/4).  alpha: AC4 (reduce channels-1).
template <typename D>
NppStatus runQualityIndex(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI,
                          int channels, bool alpha, Npp32f *pDst, Npp8u *pDeviceBuffer, cudaStream_t stream);

// ---------------------------------------------------------------------------
// CountInRange
// ---------------------------------------------------------------------------
template <typename D>
NppStatus runCountInRange1(const D *pSrc, int nSrcStep, NppiSize oSizeROI, int *pCounts, D nLowerBound,
                           D nUpperBound, Npp8u *pDeviceBuffer, cudaStream_t stream);

template <typename D>
NppStatus runCountInRangeN(const D *pSrc, int nSrcStep, NppiSize oSizeROI, int *aCounts, const D *aLowerBound,
                           const D *aUpperBound, int channels, bool alpha, Npp8u *pDeviceBuffer,
                           cudaStream_t stream);

// ---------------------------------------------------------------------------
// MSE / PSNR
// ---------------------------------------------------------------------------
template <typename D>
NppStatus runMSE(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI, int channels,
                 bool alpha, Npp32f *pMSE, Npp8u *pDeviceBuffer, cudaStream_t stream);

template <typename D>
NppStatus runPSNR(const D *pSrc1, int nSrc1Step, const D *pSrc2, int nSrc2Step, NppiSize oSizeROI, int channels,
                  bool alpha, Npp32f *pPSNR, Npp8u *pDeviceBuffer, cudaStream_t stream);

// ---------------------------------------------------------------------------
// Batch metrics (8u).  The descriptor lists are device arrays.
// ---------------------------------------------------------------------------
NppStatus runMSEBatch(const NppiImageDescriptor *pSrc1, const NppiImageDescriptor *pSrc2, int nBatchSize,
                      NppiSize oSizeROI, int channels, Npp32f *pMSE,
                      const NppiBufferDescriptor *pDeviceBufferList, bool advanced, cudaStream_t stream);
NppStatus runPSNRBatch(const NppiImageDescriptor *pSrc1, const NppiImageDescriptor *pSrc2, int nBatchSize,
                       NppiSize oSizeROI, int channels, Npp32f *pPSNR,
                       const NppiBufferDescriptor *pDeviceBufferList, bool advanced, cudaStream_t stream);

// ---------------------------------------------------------------------------
// Histogram C3R / AC4R.  hist is a host array of device pointers, one per
// colour channel; the even forms take host level arrays, the range form takes
// device level pointers.
// ---------------------------------------------------------------------------
// srcKind: 0 = Npp8u, 1 = Npp16u, 2 = Npp16s, 3 = Npp32f.  Range level arrays
// are Npp32s for the integer sources and Npp32f for 32f (matching NPP).
NppStatus runHistogramEven(const void *pSrc, int nSrcStep, NppiSize oSizeROI, Npp32s *const *pHist,
                           const int *nLevels, const Npp32s *nLowerLevel, const Npp32s *nUpperLevel, int channels,
                           bool alpha, int srcKind, cudaStream_t stream);

NppStatus runHistogramRangeI(const void *pSrc, int nSrcStep, NppiSize oSizeROI, Npp32s *const *pHist,
                             const Npp32s *const *pLevels, const int *nLevels, int channels, bool alpha, int srcKind,
                             cudaStream_t stream);
NppStatus runHistogramRangeF(const Npp32f *pSrc, int nSrcStep, NppiSize oSizeROI, Npp32s *const *pHist,
                             const Npp32f *const *pLevels, const int *nLevels, int channels, bool alpha,
                             cudaStream_t stream);

// ---------------------------------------------------------------------------
// RectStdDev (integral images) / even levels host helper
// ---------------------------------------------------------------------------
NppStatus runRectStdDevF32(const Npp32f *pSrc, int nSrcStep, const Npp64f *pSqr, int nSqrStep, Npp32f *pDst,
                           int nDstStep, NppiSize oSizeROI, NppiRect oRect, cudaStream_t stream);
NppStatus runRectStdDevS32(const Npp32s *pSrc, int nSrcStep, const Npp32s *pSqr, int nSqrStep, Npp32s *pDst,
                           int nDstStep, NppiSize oSizeROI, NppiRect oRect, int nScaleFactor, cudaStream_t stream);
NppStatus evenLevelsHost(Npp32s *hpLevels, int nLevels, Npp32s nLowerLevel, Npp32s nUpperLevel);

}  // namespace statistics
}  // namespace nppi

#endif  // NPPI_QUALITY_METRICS_EXECUTOR_H
